/**
 * Unit tests for AbstractIntegrator.acceptStep.
 * Since acceptStep is protected, we use a Testable subclass.
 */
public class AbstractIntegrator_acceptStep_TriageGen2Test {

    private TestableIntegrator integrator;
    private AbstractStepInterpolator mockInterpolator;
    private double[] y;
    private double[] yDot;

    // Mocking the ODE equations to avoid abstract implementation issues
    private ExpandableStatefulODE mockEquations;

    /**
     * Subclass to expose the protected method for testing.
     */
    private static class TestableIntegrator extends AbstractIntegrator {
        protected boolean statesInitialized = false;
        protected boolean resetOccurred = false;
        protected boolean isLastStep = false;
        protected List<EventState> eventsStates = new ArrayList<>();
        protected List<StepHandler> stepHandlers = new ArrayList<>();

        protected TestableIntegrator() {
            super("TestIntegrator");
        }

        @Override
        public void computeDerivatives(final double t, final double[] y, final double[] yDot) {
            // No-op or mock implementation
        }

        @Override
        public void integrate(ExpandableStatefulODE equations, double t) {
            // Not needed for acceptStep tests
        }

        @Override
        public void integrate(FirstOrderDifferentialEquations equations, double t0, double[] y0, double t, double[] y) {
            // Not needed for acceptStep tests
        }

        // Expose protected method for testing
        public double callAcceptStep(AbstractStepInterpolator interpolator, double[] y, double[] yDot, double tEnd) 
                throws MathIllegalStateException {
            return acceptStep(interpolator, y, yDot, tEnd);
        }

        // Expose protected setters/getters for test setup
        public void setStateInitialized(boolean initialized) {
            this.statesInitialized = initialized;
        }

        public void addEventState(EventState es) {
            this.eventsStates.add(es);
        }

        public void addStepHandler(StepHandler handler) {
            this.stepHandlers.add(handler);
        }
    }

    @Before
    public void setUp() {
        integrator = new TestableIntegrator();
        mockInterpolator = mock(AbstractStepInterpolator.class);
        y = new double[]{1.0, 2.0};
        yDot = new double[]{0.0, 0.0};
        mockEquations = mock(ExpandableStatefulODE.class);
    }

    @Test
    public void testAcceptStep_NoEvents_NormalFlow() {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.5, 2.5});

        double result = integrator.callAcceptStep(mockInterpolator, y, yDot, 2.0);

        assertEquals(1.0, result, 1e-10);
        verify(mockInterpolator).setInterpolatedTime(1.0);
        assertFalse(integrator.resetOccurred);
    }

    @Test
    public void testAcceptStep_InitializationFlow() {
        integrator.setStateInitialized(false);
        EventState mockEvent = mock(EventState.class);
        integrator.addEventState(mockEvent);

        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.5, 2.5});

        integrator.callAcceptStep(mockInterpolator, y, yDot, 2.0);

        verify(mockEvent).reinitializeBegin(mockInterpolator);
        assertTrue(integrator.statesInitialized);
    }

    @Test
    public void testAcceptStep_EventTriggersStop() {
        EventState stopEvent = mock(EventState.class);
        when(stopEvent.evaluateStep(mockInterpolator)).thenReturn(true);
        when(stopEvent.getEventTime()).thenReturn(0.5);
        when(stopEvent.stop()).thenReturn(true);

        integrator.addEventState(stopEvent);
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.2, 2.2});

        double result = integrator.callAcceptStep(mockInterpolator, y, yDot, 2.0);

        assertEquals(0.5, result, 1e-10);
        assertEquals(1.2, y[0], 1e-10);
        assertEquals(2.2, y[1], 1e-10);
    }

    @Test
    public void testAcceptStep_EventTriggersReset() {
        EventState resetEvent = mock(EventState.class);
        when(resetEvent.evaluateStep(mockInterpolator)).thenReturn(true);
        when(resetEvent.getEventTime()).thenReturn(0.5);
        when(resetEvent.stop()).thenReturn(false);
        when(resetEvent.reset(anyDouble(), any(double[].class))).thenReturn(true);

        integrator.addEventState(resetEvent);
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.2, 2.2});

        double result = integrator.callAcceptStep(mockInterpolator, y, yDot, 2.0);

        assertEquals(0.5, result, 1e-10);
        assertTrue(integrator.resetOccurred);
        assertEquals(1.2, y[0], 1e-10);
    }

    @Test
    public void testAcceptStep_MultipleEvents_ChronologicalOrder() {
        EventState event2 = mock(EventState.class);
        when(event2.evaluateStep(mockInterpolator)).thenReturn(true);
        when(event2.getEventTime()).thenReturn(0.8);
        when(event2.stop()).thenReturn(false);
        when(event2.reset(anyDouble(), any(double[].class))).thenReturn(false);

        EventState event1 = mock(EventState.class);
        when(event1.evaluateStep(mockInterpolator)).thenReturn(true);
        when(event1.getEventTime()).thenReturn(0.4);
        when(event1.stop()).thenReturn(false);
        when(event1.reset(anyDouble(), any(double[].class))).thenReturn(false);
        // Make event1 re-occur to test the while loop logic
        when(event1.evaluateStep(mockInterpolator)).thenReturn(true).thenReturn(false);

        integrator.addEventState(event2);
        integrator.addEventState(event1);

        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.0, 1.0});

        integrator.callAcceptStep(mockInterpolator, y, yDot, 2.0);

        // Verify event1 was processed before event2 due to TreeSet
        verify(event1).stepAccepted(eq(0.4), any());
        verify(event2).stepAccepted(eq(0.8), any());
    }

    @Test
    public void testAcceptStep_BackwardIntegration() {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(1.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(0.0);
        when(mockInterpolator.isForward()).thenReturn(false);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{0.5, 0.5});

        double result = integrator.callAcceptStep(mockInterpolator, y, yDot, -1.0);

        assertEquals(0.0, result, 1e-10);
    }

    @Test
    public void testAcceptStep_StepHandlerExecution() {
        StepHandler handler = mock(StepHandler.class);
        integrator.addStepHandler(handler);

        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.0, 1.0});

        integrator.callAcceptStep(mockInterpolator, y, yDot, 2.0);

        // Should be called once for the end of the step
        verify(handler, atLeastOnce()).handleStep(eq(mockInterpolator), anyBoolean());
    }

    @Test
    public void testAcceptStep_TEndPrecisionMatch() {
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(1.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.0, 1.0});

        // currentT (1.0) is effectively equal to tEnd (1.000000000000001)
        double result = integrator.callAcceptStep(mockInterpolator, y, yDot, 1.000000000000001);

        assertEquals(1.0, result, 1e-10);
    }
}
